const note = $input.first().json;

// Build a slug from the meeting title for the filename
const rawTitle = note.title || note.event_title || note.id || 'meeting-note';
const date = new Date().toISOString().split('T')[0];
const slug = rawTitle
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '')
  .substring(0, 50);

// Build markdown content from the note payload
// Fellow AI notes contain: title, summary, action_items, transcript, attendees
const sections = [];
sections.push(`# ${rawTitle}`);
sections.push(`**Date**: ${date}`);

if (note.attendees && note.attendees.length) {
  const names = note.attendees.map(a => a.name || a.email).join(', ');
  sections.push(`**Attendees**: ${names}`);
}

if (note.summary) {
  sections.push(`\n## Summary\n${note.summary}`);
}

if (note.action_items && note.action_items.length) {
  const items = note.action_items.map(i => `- ${i.description || i.text || JSON.stringify(i)}`).join('\n');
  sections.push(`\n## Action Items\n${items}`);
}

if (note.transcript) {
  sections.push(`\n## Full Transcript\n${note.transcript}`);
} else {
  // Fallback: dump the entire raw payload for Phase 0D to parse
  sections.push(`\n## Raw Payload\n\`\`\`json\n${JSON.stringify(note, null, 2)}\n\`\`\``);
}

return [{
  json: {
    path: `campaign/research/transcripts/${date}-${slug}.md`,
    content: sections.join('\n\n'),
    commitMessage: `Fellow transcript: ${rawTitle} (${date})`
  }
}];
